theorem binomial_prime_power_localization {n i p : ℕ}
    (hi : 1 ≤ i) (hin : i ≤ n) (hp : p.Prime) :
    ∃ a < i, p ^ ((n.choose i).factorization p + i.factorization p) ∣ n - a

theorem nat_prod_lt_pow_of_pointwise_lt {S : Finset ℕ} {g : ℕ → ℕ} {n : ℕ}
    (hn : 0 < n) (hS : S.Nonempty) (hg : ∀ p ∈ S, g p < n) :
    S.prod g < n ^ S.card

theorem residueChecks_sound {p q u L b0 w v : ℕ}
    (hcheck : residueChecks p q u L b0 w v = true) {d : ℤ}
    (hlo : -(w : ℤ) ≤ d) (hhi : d ≤ (w : ℤ)) :
    p ^ (u + 3 * L) < (positiveResidue (q ^ b0) v d) ^ 2

theorem residueChecks_zero {p q u L b0 w v : ℕ}
    (hcheck : residueChecks p q u L b0 w v = true) :
    p ^ (u + 3 * L) < (q ^ b0) ^ 2

theorem component_power_mul_le {C A n Y weight exponent : ℕ}
    (hproduct : C * A ≤ n) (hcofactor : Y ^ weight ≤ C ^ exponent) :
    A ^ exponent * Y ^ weight ≤ n ^ exponent

theorem rowCheck_mono_target {P Q v capA capC T T' : ℕ} {d : ℤ} {bounds : BoundsDatum}
    (hcheck : rowCheck P Q v capA capC T d bounds = true) (hT : T ≤ T') :
    rowCheck P Q v capA capC T' d bounds = true

theorem cellCheck_mono_target {P Q capA capC T T' : ℕ} {data : CellData}
    (hcheck : cellCheck P Q capA capC T data = true) (hT : T ≤ T') :
    cellCheck P Q capA capC T' data = true

theorem blockCheck_cell {p q H M T aStart aCount bStart bCount a b : ℕ}
    {data : ℕ → ℕ → CellData}
    (hcheck : blockCheck p q H M T aStart aCount bStart bCount data = true)
    (ha0 : aStart ≤ a) (ha1 : a < aStart + aCount)
    (hb0 : bStart ≤ b) (hb1 : b < bStart + bCount) :
    cellCheck (p ^ a) (q ^ b) (heightCap H M (p ^ a)) (heightCap H M (q ^ b)) T (data a b) = true

theorem blockCheck_append_rows {p q H M T aStart leftCount rightCount bStart bCount : ℕ}
    {data : ℕ → ℕ → CellData}
    (hl : blockCheck p q H M T aStart leftCount bStart bCount data = true)
    (hr : blockCheck p q H M T (aStart + leftCount) rightCount bStart bCount data = true) :
    blockCheck p q H M T aStart (leftCount + rightCount) bStart bCount data = true

theorem blockCheck_append_columns {p q H M T aStart aCount bStart leftCount rightCount : ℕ}
    {data : ℕ → ℕ → CellData}
    (hl : blockCheck p q H M T aStart aCount bStart leftCount data = true)
    (hr : blockCheck p q H M T aStart aCount (bStart + leftCount) rightCount data = true) :
    blockCheck p q H M T aStart aCount bStart (leftCount + rightCount) data = true

theorem blockCheck_mono_target {p q H M T T' aStart aCount bStart bCount : ℕ}
    {data : ℕ → ℕ → CellData}
    (hcheck : blockCheck p q H M T aStart aCount bStart bCount data = true) (hT : T ≤ T') :
    blockCheck p q H M T' aStart aCount bStart bCount data = true

theorem blockCheck_transfer_data {p q H M T aStart aCount bStart bCount : ℕ}
    {data data' : ℕ → ℕ → CellData}
    (hcheck : blockCheck p q H M T aStart aCount bStart bCount data = true)
    (hdata : ∀ a, aStart ≤ a → a < aStart + aCount →
      ∀ b, bStart ≤ b → b < bStart + bCount → data a b = data' a b) :
    blockCheck p q H M T aStart aCount bStart bCount data' = true
